/**
 * Reserves the entry port on the provider (a second group asking for the same port gets `409 PORT_IN_USE`) and returns the group in `DRAFT`.
 * @summary Create a group
 */
export const createGroupBodyNameRegExp = new RegExp('^[a-z][a-z0-9-]{0,62}$');
export const createGroupBodyDescriptionMax = 500;

export const createGroupBodyEntryPortMax = 65535;

export const createGroupBodyMembersItemServiceNameRegExp = new RegExp('^[a-z][a-z0-9-]{0,62}$');
export const createGroupBodyMembersItemContainerPortMax = 65535;

export const createGroupBodyMembersItemHealthCheckTimeoutSecondsMax = 300;



export const CreateGroupBody = zod.object({
  "providerId": zod.string(),
  "name": zod.string().regex(createGroupBodyNameRegExp),
  "description": zod.string().max(createGroupBodyDescriptionMax).optional(),
  "entryPort": zod.number().int().min(1).max(createGroupBodyEntryPortMax),
  "protocol": zod.enum(['TCP', 'UDP']).optional(),
  "members": zod.array(zod.object({
  "workloadId": zod.string(),
  "serviceName": zod.string().regex(createGroupBodyMembersItemServiceNameRegExp).optional().describe('DNS-safe name other members use; defaults to the workload name slugified'),
  "role": zod.enum(['ENTRY', 'INTERNAL', 'EXPOSED']).optional(),
  "containerPort": zod.number().int().min(1).max(createGroupBodyMembersItemContainerPortMax),
  "healthCheck": zod.object({
  "kind": zod.enum(['TCP', 'HTTP']),
  "path": zod.string().optional().describe('HTTP only'),
  "timeoutSeconds": zod.number().int().min(1).max(createGroupBodyMembersItemHealthCheckTimeoutSecondsMax).optional()
}).optional()
})).optional()
})

export const createGroupResponseTwoMembersItemHealthCheckOneTimeoutSecondsMax = 300;



export const CreateGroupResponse = zod.object({
  "id": zod.string(),
  "providerId": zod.string(),
  "providerName": zod.string(),
  "providerKind": zod.enum(['DOCKER_HOST', 'ECS_CLUSTER']),
  "name": zod.string(),
  "description": zod.string().nullable(),
  "entryPort": zod.number().int(),
  "protocol": zod.enum(['TCP', 'UDP']),
  "status": zod.enum(['DRAFT', 'APPLYING', 'APPLIED', 'DRIFTED', 'FAILED']),
  "networkRef": zod.string().nullable().describe('Docker network name or Cloud Map namespace id once applied'),
  "injectionPrefix": zod.string(),
  "injectionVersion": zod.number().int(),
  "driftReasons": zod.array(zod.string()),
  "memberCount": zod.number().int(),
  "lastAppliedAt": zod.coerce.date().nullable(),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
}).and(zod.object({
  "members": zod.array(zod.object({
  "id": zod.string(),
  "groupId": zod.string(),
  "workloadId": zod.string(),
  "workloadName": zod.string(),
  "workloadImage": zod.string(),
  "workloadStatus": zod.enum(['RUNNING', 'STOPPED', 'MISSING', 'UNKNOWN']),
  "serviceName": zod.string(),
  "role": zod.enum(['ENTRY', 'INTERNAL', 'EXPOSED']),
  "containerPort": zod.number().int(),
  "hostPort": zod.number().int().nullable().describe('Entry port for ENTRY, allocated port for EXPOSED, null for INTERNAL'),
  "healthCheck": zod.union([zod.object({
  "kind": zod.enum(['TCP', 'HTTP']),
  "path": zod.string().optional().describe('HTTP only'),
  "timeoutSeconds": zod.number().int().min(1).max(createGroupResponseTwoMembersItemHealthCheckOneTimeoutSecondsMax).optional()
}),zod.null()]),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
})),
  "allocations": zod.array(zod.object({
  "id": zod.string(),
  "providerId": zod.string(),
  "groupId": zod.string(),
  "memberId": zod.string().nullable(),
  "hostPort": zod.number().int(),
  "protocol": zod.enum(['TCP', 'UDP']),
  "state": zod.enum(['RESERVED', 'APPLIED', 'RELEASED']),
  "createdAt": zod.coerce.date(),
  "releasedAt": zod.coerce.date().nullable()
}))
}))


